-- Community notes: tables, download counts, and the full notes library for Data Science
-- (Foundation, Diploma and Degree) imported from the public AceGrade notes list.
--
-- NOT RUN YET. Run it once in the Supabase SQL editor. It is safe to run again:
-- tables are created only if missing and a note is only inserted when its Drive link is not already there.
--
-- Imported notes are inserted as 'approved' with no user attached, and start with a download count of 0. Subject names match the names used on the Resources page.

CREATE TABLE IF NOT EXISTS public.resources_notes (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id             UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  degree              TEXT NOT NULL CHECK (degree IN ('data-science', 'electronic-systems')),
  level               TEXT NOT NULL CHECK (level IN ('foundation', 'diploma', 'degree')),
  subject             TEXT NOT NULL,
  notes_week_from     INTEGER NOT NULL DEFAULT 1,
  notes_week_to       INTEGER NOT NULL DEFAULT 1,
  title               TEXT NOT NULL,
  contributor_name    TEXT NOT NULL,
  notes_content_label TEXT NOT NULL DEFAULT '',
  drive_link          TEXT NOT NULL,
  status              TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  downloads           INTEGER NOT NULL DEFAULT 0,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- If the table already existed from before, make sure it has what the app now reads.
ALTER TABLE public.resources_notes ADD COLUMN IF NOT EXISTS downloads INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.resources_notes ALTER COLUMN user_id DROP NOT NULL;

CREATE INDEX IF NOT EXISTS idx_resources_notes_lookup ON public.resources_notes (degree, level, subject) WHERE status = 'approved';
CREATE INDEX IF NOT EXISTS idx_resources_notes_drive  ON public.resources_notes (drive_link);

CREATE TABLE IF NOT EXISTS public.resources_note_stars (
  note_id    UUID NOT NULL REFERENCES public.resources_notes(id) ON DELETE CASCADE,
  user_id    UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (note_id, user_id)
);

-- Only server routes (service role) touch these tables.
ALTER TABLE public.resources_notes      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.resources_note_stars ENABLE ROW LEVEL SECURITY;

-- Count a download. Called by the app through the service role.
CREATE OR REPLACE FUNCTION public.bump_note_downloads(p_note UUID)
RETURNS INTEGER
LANGUAGE sql
SET search_path = public
AS $$
  UPDATE public.resources_notes SET downloads = downloads + 1 WHERE id = p_note AND status = 'approved' RETURNING downloads;
$$;

REVOKE ALL ON FUNCTION public.bump_note_downloads(UUID) FROM PUBLIC, anon, authenticated;

